VALUES
(
  'Lesson Note: Primary 1 English Studies - Letter Sounds: a, b, c, d', 'lesson-note-primary-1-english-studies-letter-sounds-a-b-c-d',
  'A complete lesson note for Primary 1 English Studies on letter sounds: a, b, c, d, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Studies &nbsp; <strong>Class:</strong> Primary 1 &nbsp; <strong>Duration:</strong> 30 minutes</p><p><strong>Topic:</strong> Letter Sounds: a, b, c, d</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>say the sounds of the letters a, b, c and d</li><li>name one object that starts with each sound</li></ul><p><strong>Previous knowledge:</strong> Pupils can recognise some letters of the alphabet.</p><p><strong>Materials:</strong> Letter cards (a, b, c, d), pictures or real objects: apple, ball, cup/cat, doll.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Sing the alphabet song. Ask pupils to name any letter they know.</li><li><strong>(10 min)</strong> Show the card for 'a' with an apple. Say the sound clearly (/a/), pupils repeat. Repeat for b (ball), c (cat), d (doll).</li><li><strong>(10 min)</strong> Say a word; pupils point to the card that matches its first sound.</li><li><strong>(5 min)</strong> Pupils say the four sounds together, then in pairs.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Say the sound of the letter b.</li><li>Which letter does 'doll' start with?</li><li>Name one thing that starts with 'c'.</li></ol><p><strong>Summary:</strong> Review the four letters and their sounds.</p><p><strong>Assignment:</strong> Draw one object for each of the letters a, b, c and d.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 1','english','phonics','letter sounds','lesson note'], 4,
  'Lesson Note: Primary 1 English Studies - Letter Sounds: a, b, c, d (Nigeria)',
  'A complete lesson note for Primary 1 English Studies on letter sounds: a, b, c, d, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 1 Mathematics - Counting and Writing Numbers 1-20', 'lesson-note-primary-1-mathematics-counting-and-writing-numbers-1-20',
  'A complete lesson note for Primary 1 Mathematics on counting and writing numbers 1-20, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> Primary 1 &nbsp; <strong>Duration:</strong> 30 minutes</p><p><strong>Topic:</strong> Counting and Writing Numbers 1-20</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>count objects up to 20</li><li>write the numbers 1 to 20</li></ul><p><strong>Previous knowledge:</strong> Pupils can count from 1 to 10.</p><p><strong>Materials:</strong> Bottle tops or stones, number cards 1-20, chalkboard.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Count 1 to 10 together while clapping.</li><li><strong>(10 min)</strong> Show groups of bottle tops. Pupils count aloud, then pick the matching number card. Extend to 20.</li><li><strong>(10 min)</strong> Demonstrate writing 11 to 20 on the board. Pupils write in the air, then on slates.</li><li><strong>(5 min)</strong> Game: teacher shows a number card; pupils bring that many bottle tops.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Count these 15 bottle tops.</li><li>Write the number after 12.</li><li>Which number comes before 20?</li></ol><p><strong>Summary:</strong> Review counting and writing 1 to 20.</p><p><strong>Assignment:</strong> Write the numbers 1 to 20 in your exercise book.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 1','mathematics','counting','numbers','lesson note'], 4,
  'Lesson Note: Primary 1 Mathematics - Counting and Writing Numbers 1-20 (Nigeria)',
  'A complete lesson note for Primary 1 Mathematics on counting and writing numbers 1-20, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 2 English Studies - Naming Words (Nouns)', 'lesson-note-primary-2-english-studies-naming-words-nouns',
  'A complete lesson note for Primary 2 English Studies on naming words (nouns), with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Studies &nbsp; <strong>Class:</strong> Primary 2 &nbsp; <strong>Duration:</strong> 35 minutes</p><p><strong>Topic:</strong> Naming Words (Nouns)</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>explain that a noun is a naming word</li><li>identify nouns for people, animals, places and things in sentences</li></ul><p><strong>Previous knowledge:</strong> Pupils can read and write simple sentences.</p><p><strong>Materials:</strong> Chart with pictures: girl, dog, market, book; sentence strips.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask pupils to name things in the classroom.</li><li><strong>(10 min)</strong> Explain: words that name people, animals, places and things are nouns. Show the chart and sort pictures into four groups.</li><li><strong>(10 min)</strong> Write 'The boy has a book.' Pupils underline the nouns (boy, book). Repeat with two more sentences.</li><li><strong>(10 min)</strong> In groups, pupils write three nouns for each of the four groups.</li></ol><p><strong>Evaluation:</strong></p><ol><li>What is a noun?</li><li>Underline the nouns: The cat sat on the mat.</li><li>Give two nouns that name places.</li></ol><p><strong>Summary:</strong> A noun names a person, animal, place or thing.</p><p><strong>Assignment:</strong> Write five sentences and underline the noun in each.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 2','english','nouns','grammar','lesson note'], 4,
  'Lesson Note: Primary 2 English Studies - Naming Words (Nouns) (Nigeria)',
  'A complete lesson note for Primary 2 English Studies on naming words (nouns), with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 2 Basic Science - Parts of the Body and the Five Senses', 'lesson-note-primary-2-basic-science-parts-of-the-body-and-the-five-senses',
  'A complete lesson note for Primary 2 Basic Science on parts of the body and the five senses, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Basic Science &nbsp; <strong>Class:</strong> Primary 2 &nbsp; <strong>Duration:</strong> 35 minutes</p><p><strong>Topic:</strong> Parts of the Body and the Five Senses</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>name the five sense organs</li><li>state what each sense organ does</li></ul><p><strong>Previous knowledge:</strong> Pupils can name some parts of the body.</p><p><strong>Materials:</strong> Chart of the body, a flower or fruit with a smell, a bell, a sweet and a bitter leaf (optional, with care).</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask: How do you know the food is ready? Take answers.</li><li><strong>(10 min)</strong> Show the chart. Teach: eyes (see), ears (hear), nose (smell), tongue (taste), skin (feel).</li><li><strong>(10 min)</strong> Activity: pupils hear a bell with eyes closed, smell a fruit, and feel the desk and a cloth. Pupils say which sense they used.</li><li><strong>(10 min)</strong> Pupils draw and label the five sense organs.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Which part of the body do we use to hear?</li><li>Name the sense we use to feel hot and cold.</li><li>Which sense organ helps us smell?</li></ol><p><strong>Summary:</strong> We have five senses: sight, hearing, smell, taste and touch.</p><p><strong>Assignment:</strong> Draw the face and label the eyes, ears, nose and tongue.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 2','basic science','senses','body','lesson note'], 4,
  'Lesson Note: Primary 2 Basic Science - Parts of the Body and the Five Senses (Nigeria)',
  'A complete lesson note for Primary 2 Basic Science on parts of the body and the five senses, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 3 Mathematics - Multiplication as Repeated Addition', 'lesson-note-primary-3-mathematics-multiplication-as-repeated-addition',
  'A complete lesson note for Primary 3 Mathematics on multiplication as repeated addition, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> Primary 3 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Multiplication as Repeated Addition</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>explain multiplication as repeated addition</li><li>solve simple multiplication problems up to 5 x 5</li></ul><p><strong>Previous knowledge:</strong> Pupils can add numbers and count in twos, threes and fives.</p><p><strong>Materials:</strong> Bottle tops, drawn groups on the board.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Oral drill: count in 2s and 5s.</li><li><strong>(10 min)</strong> Make 3 groups of 4 bottle tops. Write 4 + 4 + 4 = 12. Introduce 3 x 4 = 12 ('3 groups of 4').</li><li><strong>(10 min)</strong> Show 2 x 5 = 5 + 5 = 10 and 4 x 3 = 3 + 3 + 3 + 3 = 12 on the board.</li><li><strong>(10 min)</strong> Pairs make their own groups with bottle tops and write the repeated addition and the multiplication sentence.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Write 2 x 3 as repeated addition.</li><li>What is 4 x 2?</li><li>3 groups of 5 is how many?</li></ol><p><strong>Summary:</strong> Multiplication is a quick way of adding the same number many times.</p><p><strong>Assignment:</strong> Write 5 multiplication sentences with their repeated addition.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 3','mathematics','multiplication','lesson note'], 4,
  'Lesson Note: Primary 3 Mathematics - Multiplication as Repeated Addition (Nigeria)',
  'A complete lesson note for Primary 3 Mathematics on multiplication as repeated addition, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 3 National Values - Rules at Home and at School', 'lesson-note-primary-3-national-values-rules-at-home-and-at-school',
  'A complete lesson note for Primary 3 National Values on rules at home and at school, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> National Values &nbsp; <strong>Class:</strong> Primary 3 &nbsp; <strong>Duration:</strong> 35 minutes</p><p><strong>Topic:</strong> Rules at Home and at School</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>state two rules at home and two rules at school</li><li>explain why we obey rules</li></ul><p><strong>Previous knowledge:</strong> Pupils know some school rules.</p><p><strong>Materials:</strong> Chart of school rules, pictures showing good and bad behaviour.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask: What happens if everyone talks at the same time?</li><li><strong>(10 min)</strong> List rules at home (greet elders, do chores) and at school (come on time, keep quiet in class, keep the school clean).</li><li><strong>(10 min)</strong> Discuss pictures of good and bad behaviour. Pupils say which follows the rule and why.</li><li><strong>(10 min)</strong> Pairs act a short scene showing a rule being followed.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Name one rule at home.</li><li>Why do we keep rules at school?</li><li>What can happen if we break rules?</li></ol><p><strong>Summary:</strong> Rules keep us safe and help us live well with others.</p><p><strong>Assignment:</strong> Write two rules at home and two rules at school.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 3','national values','rules','civic','lesson note'], 4,
  'Lesson Note: Primary 3 National Values - Rules at Home and at School (Nigeria)',
  'A complete lesson note for Primary 3 National Values on rules at home and at school, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 4 English Studies - Verbs (Action Words)', 'lesson-note-primary-4-english-studies-verbs-action-words',
  'A complete lesson note for Primary 4 English Studies on verbs (action words), with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Studies &nbsp; <strong>Class:</strong> Primary 4 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Verbs (Action Words)</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>define a verb as a doing word</li><li>identify verbs in sentences</li><li>use verbs to complete sentences</li></ul><p><strong>Previous knowledge:</strong> Pupils know nouns.</p><p><strong>Materials:</strong> Word cards with action words (run, jump, eat, write), sentence chart.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Mime actions; pupils guess the action.</li><li><strong>(10 min)</strong> Explain: a verb tells what someone or something does. Write 'The girl sings.' and circle 'sings'.</li><li><strong>(10 min)</strong> Write five sentences; pupils come out to circle the verb.</li><li><strong>(10 min)</strong> Pupils complete: The bird ___ (flies/fly). Write three sentences of their own.</li></ol><p><strong>Evaluation:</strong></p><ol><li>What is a verb?</li><li>Circle the verb: Ade kicks the ball.</li><li>Write a sentence with the verb 'jump'.</li></ol><p><strong>Summary:</strong> A verb is a word that shows action.</p><p><strong>Assignment:</strong> Write five sentences and underline the verb in each.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
