),
(
  'Lesson Note: Primary 4 Basic Science and Technology - Living and Non-Living Things', 'lesson-note-primary-4-basic-science-and-technology-living-and-non-living-things',
  'A complete lesson note for Primary 4 Basic Science and Technology on living and non-living things, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Basic Science and Technology &nbsp; <strong>Class:</strong> Primary 4 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Living and Non-Living Things</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>list the characteristics of living things</li><li>sort things into living and non-living</li></ul><p><strong>Previous knowledge:</strong> Pupils can name common plants, animals and objects.</p><p><strong>Materials:</strong> A potted plant, pictures of animals and objects, a stone, a toy car.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Show a plant and a stone; ask how they are different.</li><li><strong>(10 min)</strong> Teach characteristics of living things: they feed, breathe, grow, move, reproduce and respond to their surroundings.</li><li><strong>(10 min)</strong> Test objects (plant, pupil, stone, toy car) against each characteristic on a chart.</li><li><strong>(10 min)</strong> Pupils sort picture cards into two groups.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Name three characteristics of living things.</li><li>Is a stone living or non-living? Why?</li><li>Give two examples of living things.</li></ol><p><strong>Summary:</strong> Living things feed, breathe, grow, move, reproduce and respond.</p><p><strong>Assignment:</strong> Draw two living and two non-living things and label them.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 4-6 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri4-6.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 4','basic science','living things','lesson note'], 4,
  'Lesson Note: Primary 4 Basic Science and Technology - Living and Non-Living Things (Nigeria)',
  'A complete lesson note for Primary 4 Basic Science and Technology on living and non-living things, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 5 Mathematics - Equivalent Fractions', 'lesson-note-primary-5-mathematics-equivalent-fractions',
  'A complete lesson note for Primary 5 Mathematics on equivalent fractions, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> Primary 5 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Equivalent Fractions</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>explain that equivalent fractions have the same value</li><li>find equivalent fractions by multiplying the top and bottom by the same number</li></ul><p><strong>Previous knowledge:</strong> Pupils know halves, thirds and quarters.</p><p><strong>Materials:</strong> Paper strips or circles for folding, chart.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Fold a paper strip in half; shade 1/2.</li><li><strong>(10 min)</strong> Fold into 4 parts: 2/4 is the same size as 1/2. Show 1/2 = 2/4 = 3/6.</li><li><strong>(10 min)</strong> Rule: multiply the numerator and denominator by the same number. Example: 2/3 = (2x2)/(3x2) = 4/6.</li><li><strong>(10 min)</strong> Pupils find two equivalent fractions for 1/3 and 3/4.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Find: 1/3 = ?/6</li><li>Write one fraction equal to 3/4.</li><li>Is 2/5 equal to 4/10?</li></ol><p><strong>Summary:</strong> Equivalent fractions look different but have the same value.</p><p><strong>Assignment:</strong> Write two equivalent fractions for each: 1/2, 2/3, 1/4.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 4-6 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri4-6.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 5','mathematics','fractions','lesson note'], 4,
  'Lesson Note: Primary 5 Mathematics - Equivalent Fractions (Nigeria)',
  'A complete lesson note for Primary 5 Mathematics on equivalent fractions, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 5 English Studies - Simple Present and Simple Past Tense', 'lesson-note-primary-5-english-studies-simple-present-and-simple-past-tense',
  'A complete lesson note for Primary 5 English Studies on simple present and simple past tense, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Studies &nbsp; <strong>Class:</strong> Primary 5 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Simple Present and Simple Past Tense</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>identify verbs in the simple present and simple past tense</li><li>change sentences from present to past</li></ul><p><strong>Previous knowledge:</strong> Pupils know verbs.</p><p><strong>Materials:</strong> Sentence cards, table of present and past forms.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask: What do you do every day? What did you do yesterday?</li><li><strong>(10 min)</strong> Teach simple present (She walks to school) and simple past (She walked to school). Show regular -ed verbs: walk-walked, play-played.</li><li><strong>(10 min)</strong> Show irregular verbs: go-went, eat-ate, write-wrote. Pupils copy the table.</li><li><strong>(10 min)</strong> Pupils change five sentences from present to past.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Write the past tense of 'play'.</li><li>Change to past: He goes to market.</li><li>What is the past tense of 'eat'?</li></ol><p><strong>Summary:</strong> The simple past tense tells of actions that are finished.</p><p><strong>Assignment:</strong> Write five sentences in the simple past tense.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 4-6 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri4-6.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 5','english','tenses','grammar','lesson note'], 4,
  'Lesson Note: Primary 5 English Studies - Simple Present and Simple Past Tense (Nigeria)',
  'A complete lesson note for Primary 5 English Studies on simple present and simple past tense, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 6 Mathematics - Percentages', 'lesson-note-primary-6-mathematics-percentages',
  'A complete lesson note for Primary 6 Mathematics on percentages, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> Primary 6 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Percentages</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>explain per cent as 'out of 100'</li><li>find a percentage of a quantity</li></ul><p><strong>Previous knowledge:</strong> Pupils can work with fractions and multiplication.</p><p><strong>Materials:</strong> Hundred-square chart, chalkboard.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Shade 50 squares on a hundred-square chart. Ask what part is shaded.</li><li><strong>(10 min)</strong> Teach: 50 out of 100 is 50%. Link to fractions: 50% = 1/2, 25% = 1/4.</li><li><strong>(10 min)</strong> Worked examples: 50% of 200 = 100; 25% of 80 = 20; 10% of 150 = 15. Method: divide by 100, then multiply.</li><li><strong>(10 min)</strong> Pupils solve three problems in pairs.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Find 20% of 50.</li><li>Find 75% of 40.</li><li>Find 5% of 200.</li></ol><p><strong>Summary:</strong> A percentage is a number out of 100.</p><p><strong>Assignment:</strong> Find: 10% of 60, 50% of 90, 25% of 200.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 4-6 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri4-6.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 6','mathematics','percentages','lesson note'], 4,
  'Lesson Note: Primary 6 Mathematics - Percentages (Nigeria)',
  'A complete lesson note for Primary 6 Mathematics on percentages, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: Primary 6 Basic Science and Technology - Water: Sources, Pollution and Purification', 'lesson-note-primary-6-basic-science-and-technology-water-sources-pollution-and-purificatio',
  'A complete lesson note for Primary 6 Basic Science and Technology on water: sources, pollution and purification, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Basic Science and Technology &nbsp; <strong>Class:</strong> Primary 6 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Water: Sources, Pollution and Purification</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>list sources of water</li><li>state causes of water pollution</li><li>describe ways of making water safe to drink</li></ul><p><strong>Previous knowledge:</strong> Pupils know that water is needed by living things.</p><p><strong>Materials:</strong> Pictures of rivers, wells and boreholes, a jar of dirty water, a cloth for filtering.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask where pupils get water at home.</li><li><strong>(10 min)</strong> Sources: rain, rivers, streams, wells, boreholes. Causes of pollution: dumping refuse, oil spills, open defecation, washing in streams.</li><li><strong>(10 min)</strong> Purification: boiling, filtering through clean cloth or sand, and treating with approved chemicals. Demonstrate filtering dirty water.</li><li><strong>(10 min)</strong> Discuss diseases from dirty water (cholera, typhoid) and how to prevent them.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Name two sources of water.</li><li>Give two causes of water pollution.</li><li>Why should we boil drinking water?</li></ol><p><strong>Summary:</strong> Clean water is needed for health. Pollute less, purify more.</p><p><strong>Assignment:</strong> List three ways to keep your water source clean.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Primary 4-6 curriculum", "url": "https://nerdc.gov.ng/content_manager/pri4-6.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['primary 6','basic science','water','health','lesson note'], 4,
  'Lesson Note: Primary 6 Basic Science and Technology - Water: Sources, Pollution and Purification (Nigeria)',
  'A complete lesson note for Primary 6 Basic Science and Technology on water: sources, pollution and purification, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: JSS 1 Mathematics - Simplifying Algebraic Expressions', 'lesson-note-jss-1-mathematics-simplifying-algebraic-expressions',
  'A complete lesson note for JSS 1 Mathematics on simplifying algebraic expressions, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> JSS 1 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Simplifying Algebraic Expressions</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>identify like terms</li><li>simplify expressions by collecting like terms</li></ul><p><strong>Previous knowledge:</strong> Students know the basic operations and the idea of letters standing for numbers.</p><p><strong>Materials:</strong> Chalkboard, cards with terms such as 3a, 2a, 5b.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Revision: 3 apples + 2 apples = 5 apples. Link to 3a + 2a.</li><li><strong>(10 min)</strong> Define like terms (same letter): 3a and 2a are like; 3a and 2b are not.</li><li><strong>(10 min)</strong> Examples: 3a + 2a = 5a; 5x - 2x = 3x; 2a + 3b + 4a = 6a + 3b.</li><li><strong>(10 min)</strong> Students simplify five expressions in pairs.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Simplify 7y + 2y.</li><li>Simplify 6m - 4m.</li><li>Simplify 3p + 2q + 5p.</li></ol><p><strong>Summary:</strong> Only like terms can be added or subtracted.</p><p><strong>Assignment:</strong> Simplify: 4a + 5a, 9x - 3x, 2m + 3n + 4m.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: JSS 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/jss1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['jss 1','mathematics','algebra','lesson note'], 4,
  'Lesson Note: JSS 1 Mathematics - Simplifying Algebraic Expressions (Nigeria)',
  'A complete lesson note for JSS 1 Mathematics on simplifying algebraic expressions, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: JSS 2 English Studies - Writing a Formal Letter', 'lesson-note-jss-2-english-studies-writing-a-formal-letter',
  'A complete lesson note for JSS 2 English Studies on writing a formal letter, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Studies &nbsp; <strong>Class:</strong> JSS 2 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Writing a Formal Letter</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>list the parts of a formal letter</li><li>write a formal letter to a school principal</li></ul><p><strong>Previous knowledge:</strong> Students can write informal letters.</p><p><strong>Materials:</strong> Sample formal letter on chart paper.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask: When would you write to a principal or an official?</li><li><strong>(10 min)</strong> Show the layout: writer's address, date, receiver's title and address, salutation (Dear Sir/Madam), subject heading, body, 'Yours faithfully', name.</li><li><strong>(10 min)</strong> Compare formal and informal letters: tone, language, layout.</li><li><strong>(10 min)</strong> Students plan a letter applying for a place in the school football team.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Name three parts of a formal letter.</li><li>How do you end a letter that begins 'Dear Sir'?</li><li>Why do we use a subject heading?</li></ol><p><strong>Summary:</strong> A formal letter uses polite, direct language and a fixed layout.</p><p><strong>Assignment:</strong> Write a formal letter to your principal requesting permission for a school trip.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: JSS 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/jss1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['jss 2','english','formal letter','writing','lesson note'], 4,
  'Lesson Note: JSS 2 English Studies - Writing a Formal Letter (Nigeria)',
  'A complete lesson note for JSS 2 English Studies on writing a formal letter, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: JSS 3 Basic Science - Photosynthesis', 'lesson-note-jss-3-basic-science-photosynthesis',
  'A complete lesson note for JSS 3 Basic Science on photosynthesis, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Basic Science &nbsp; <strong>Class:</strong> JSS 3 &nbsp; <strong>Duration:</strong> 40 minutes</p><p><strong>Topic:</strong> Photosynthesis</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>define photosynthesis</li><li>state the raw materials and products</li><li>write the word equation</li></ul><p><strong>Previous knowledge:</strong> Students know the parts of a leaf and that plants make food.</p><p><strong>Materials:</strong> Leaf, chart showing photosynthesis, chalkboard.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask how plants get their food.</li><li><strong>(10 min)</strong> Explain: in sunlight, green plants use chlorophyll to make glucose from carbon dioxide and water and release oxygen.</li><li><strong>(10 min)</strong> Write: carbon dioxide + water -> (light, chlorophyll) -> glucose + oxygen. Chemical form: 6CO2 + 6H2O -> C6H12O6 + 6O2.</li><li><strong>(10 min)</strong> Discuss why photosynthesis matters for food and oxygen.</li></ol><p><strong>Evaluation:</strong></p><ol><li>State two raw materials for photosynthesis.</li><li>Name the products.</li><li>Where does photosynthesis take place?</li></ol><p><strong>Summary:</strong> Photosynthesis makes food and oxygen for living things.</p><p><strong>Assignment:</strong> Draw and label a diagram of photosynthesis in a leaf.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: JSS 1-3 curriculum", "url": "https://nerdc.gov.ng/content_manager/jss1-3.html"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['jss 3','basic science','photosynthesis','plants','lesson note'], 4,
  'Lesson Note: JSS 3 Basic Science - Photosynthesis (Nigeria)',
  'A complete lesson note for JSS 3 Basic Science on photosynthesis, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: SS 1 Mathematics - Laws of Indices', 'lesson-note-ss-1-mathematics-laws-of-indices',
  'A complete lesson note for SS 1 Mathematics on laws of indices, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Mathematics &nbsp; <strong>Class:</strong> SS 1 &nbsp; <strong>Duration:</strong> 45 minutes</p><p><strong>Topic:</strong> Laws of Indices</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>state the laws of indices</li><li>simplify expressions using the laws</li></ul><p><strong>Previous knowledge:</strong> Students know squares, cubes and powers.</p><p><strong>Materials:</strong> Chalkboard, worked examples.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Revision: 2<sup>3</sup> = 2 x 2 x 2 = 8.</li><li><strong>(15 min)</strong> Laws: a<sup>m</sup> x a<sup>n</sup> = a<sup>m+n</sup>; a<sup>m</sup> / a<sup>n</sup> = a<sup>m-n</sup>; (a<sup>m</sup>)<sup>n</sup> = a<sup>mn</sup>; a<sup>0</sup> = 1.</li><li><strong>(15 min)</strong> Examples: 2<sup>3</sup> x 2<sup>4</sup> = 2<sup>7</sup> = 128; 5<sup>6</sup> / 5<sup>4</sup> = 5<sup>2</sup> = 25; (3<sup>2</sup>)<sup>3</sup> = 3<sup>6</sup> = 729.</li><li><strong>(10 min)</strong> Students solve five problems and the teacher marks on the board.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Simplify 3<sup>2</sup> x 3<sup>3</sup>.</li><li>Simplify 10<sup>5</sup> / 10<sup>2</sup>.</li><li>Evaluate (2<sup>2</sup>)<sup>3</sup>.</li></ol><p><strong>Summary:</strong> Multiply: add the powers. Divide: subtract the powers. Power of a power: multiply.</p><p><strong>Assignment:</strong> Simplify: 4<sup>3</sup> x 4<sup>2</sup>, 7<sup>5</sup> / 7<sup>3</sup>, (5<sup>2</sup>)<sup>2</sup>.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Basic and Senior Secondary Curriculum Offerings (PDF)", "url": "https://nerdc.gov.ng/content_manager/Basic%20and%20Senior%20Secondary%20Education%20Curriculum%20Offerings.pdf"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['ss 1','mathematics','indices','lesson note'], 4,
  'Lesson Note: SS 1 Mathematics - Laws of Indices (Nigeria)',
  'A complete lesson note for SS 1 Mathematics on laws of indices, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: SS 2 English Language - Summary Writing', 'lesson-note-ss-2-english-language-summary-writing',
  'A complete lesson note for SS 2 English Language on summary writing, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> English Language &nbsp; <strong>Class:</strong> SS 2 &nbsp; <strong>Duration:</strong> 45 minutes</p><p><strong>Topic:</strong> Summary Writing</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>identify the main points in a passage</li><li>write a summary in the required number of words</li></ul><p><strong>Previous knowledge:</strong> Students can read for meaning and write complete sentences.</p><p><strong>Materials:</strong> A short passage (about 250 words), question paper.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Explain what a summary is and why it is tested in exams.</li><li><strong>(15 min)</strong> Teach the steps: read the question first, read the passage, underline relevant points, list them in your own words, join in a short paragraph.</li><li><strong>(15 min)</strong> Practise with the passage: students underline points and list them.</li><li><strong>(10 min)</strong> Students write a summary of 50 words and check the word count.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Why should you read the question first?</li><li>What should you leave out of a summary?</li><li>How do you stay within the word limit?</li></ol><p><strong>Summary:</strong> A good summary is short, accurate and in your own words.</p><p><strong>Assignment:</strong> Write a 60-word summary of a newspaper article.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Basic and Senior Secondary Curriculum Offerings (PDF)", "url": "https://nerdc.gov.ng/content_manager/Basic%20and%20Senior%20Secondary%20Education%20Curriculum%20Offerings.pdf"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['ss 2','english','summary','waec','lesson note'], 4,
  'Lesson Note: SS 2 English Language - Summary Writing (Nigeria)',
  'A complete lesson note for SS 2 English Language on summary writing, with objectives, steps, evaluation and assignment.', false
),
(
  'Lesson Note: SS 3 Civic Education - The Rule of Law', 'lesson-note-ss-3-civic-education-the-rule-of-law',
  'A complete lesson note for SS 3 Civic Education on the rule of law, with objectives, steps, evaluation and assignment.',
  $b$<p><strong>Subject:</strong> Civic Education &nbsp; <strong>Class:</strong> SS 3 &nbsp; <strong>Duration:</strong> 45 minutes</p><p><strong>Topic:</strong> The Rule of Law</p><p><strong>Objectives:</strong> By the end of the lesson, students should be able to:</p><ul><li>define the rule of law</li><li>state its importance and the ways it can be threatened</li></ul><p><strong>Previous knowledge:</strong> Students know the meaning of law and government.</p><p><strong>Materials:</strong> Chart with key points, news headlines.</p><h3>Presentation</h3><ol><li><strong>(5 min)</strong> Ask: Should anyone be above the law?</li><li><strong>(15 min)</strong> Teach: the rule of law means everyone, including leaders, is subject to the law. Importance: equality, protection of rights, order, accountability.</li><li><strong>(15 min)</strong> Threats: corruption, abuse of power, delay of justice, disobeying court orders.</li><li><strong>(10 min)</strong> Group discussion: one example of the rule of law at work in your community.</li></ol><p><strong>Evaluation:</strong></p><ol><li>Define the rule of law.</li><li>State two importance of the rule of law.</li><li>Name two threats to the rule of law.</li></ol><p><strong>Summary:</strong> The rule of law means that no person is above the law.</p><p><strong>Assignment:</strong> Write a short essay on why the rule of law matters.</p><p><em>Adapt this note to your scheme of work and check topic placement against the official curriculum for your class.</em></p>$b$,
  'Lesson Notes', 'article', NULL,
  $j$[{"label": "NERDC: Basic and Senior Secondary Curriculum Offerings (PDF)", "url": "https://nerdc.gov.ng/content_manager/Basic%20and%20Senior%20Secondary%20Education%20Curriculum%20Offerings.pdf"}, {"label": "NERDC: Teachers' Handbook (PDF)", "url": "https://nerdc.gov.ng/content_manager/pdf_files/teachers_handbook.pdf"}]$j$::jsonb,
  ARRAY['ss 3','civic education','rule of law','lesson note'], 4,
  'Lesson Note: SS 3 Civic Education - The Rule of Law (Nigeria)',
  'A complete lesson note for SS 3 Civic Education on the rule of law, with objectives, steps, evaluation and assignment.', false
)
